CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(char_length(title) BETWEEN 2 AND 160), slug text NOT NULL UNIQUE CHECK(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), department text NOT NULL DEFAULT '', employment_type text NOT NULL DEFAULT 'Full-Time, Permanent', work_location text NOT NULL DEFAULT 'Work From Home', shift text NOT NULL DEFAULT '', experience text NOT NULL DEFAULT '', openings text NOT NULL DEFAULT '', description text NOT NULL CHECK(char_length(description) BETWEEN 10 AND 8000), application_email text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), date_posted date, eligibility_country text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.jobs TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.jobs TO authenticated; GRANT ALL ON public.jobs TO service_role;
ALTER TABLE public.jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_jobs ON public.jobs FOR SELECT TO anon,authenticated USING(status='published');
CREATE POLICY admin_jobs ON public.jobs FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX jobs_publication_idx ON public.jobs(status,created_at DESC);
CREATE TABLE public.contact_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(char_length(name) BETWEEN 1 AND 100), email text NOT NULL CHECK(char_length(email)<=254), message text NOT NULL CHECK(char_length(message) BETWEEN 1 AND 3000), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','reviewed','archived')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.contact_submissions TO authenticated; GRANT ALL ON public.contact_submissions TO service_role;
ALTER TABLE public.contact_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_enquiries_read ON public.contact_submissions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_enquiries_update ON public.contact_submissions FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX enquiries_created_idx ON public.contact_submissions(created_at DESC);
CREATE TABLE public.site_settings (id text PRIMARY KEY DEFAULT 'main' CHECK(id='main'), contact_email text NOT NULL DEFAULT 'Syedabdullahmadani0408@gmail.com', contact_phone text NOT NULL DEFAULT '+91 70137 03786', whatsapp_number text NOT NULL DEFAULT '917013703786', footer_description text NOT NULL DEFAULT 'Business advisory, outsourced sales, and offshore support. Practical capabilities for a global world.', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_settings TO anon; GRANT SELECT,INSERT,UPDATE ON public.site_settings TO authenticated; GRANT ALL ON public.site_settings TO service_role;
ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_settings_read ON public.site_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY admin_settings_insert ON public.site_settings FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_settings_update ON public.site_settings FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER jobs_updated BEFORE UPDATE ON public.jobs FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER settings_updated BEFORE UPDATE ON public.site_settings FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
